const __pageData = JSON.parse('{"title":"第 5 章：GPU 编程：从向量加法到矩阵乘法","description":"沿 learn-cuda 理解线程、内存与协作，展开矩乘、归约、Softmax、滤波、FP6、Attention 和 GEMV。","frontmatter":{"title":"第 5 章：GPU 编程：从向量加法到矩阵乘法","description":"沿 learn-cuda 理解线程、内存与协作，展开矩乘、归约、Softmax、滤波、FP6、Attention 和 GEMV。","pageClass":"burn-course"},"headers":[],"relativePath":"burn/gpu-programming.md","filePath":"burn/gpu-programming.md"}');
